<?php $this->layout('default'); use Moves\Services\PlatformBilling as B; use Moves\Support\CmsView as V;
$filters = ['q' => V::queryString('q'), 'status' => V::queryString('status')]; $result = B::charges($filters, V::queryPage()); ?>
<div class="cms-alert cms-alert-info">Nenhum provedor de pagamento está integrado. Esta área registra as cobranças da assinatura Realizze e não executa cobranças reais. Contas a Receber dos clientes ficam no App.</div>
<div class="cms-card"><form class="cms-filters" method="get"><?= V::field('Pesquisar', 'q', $filters['q'], ['type' => 'search']) ?><?= V::field('Situação', 'status', $filters['status'], ['type' => 'select', 'choices' => ['' => 'Todas'] + V::CHARGE_STATUS]) ?><button class="cms-btn">Filtrar</button></form>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhuma cobrança encontrada.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Cobranças"><table><thead><tr><th>Referência</th><th>Assinante</th><th>Plano</th><th>Vencimento</th><th class="num">Valor</th><th>Situação</th></tr></thead><tbody><?php foreach ($result['rows'] as $c): ?><tr><td><a href="/cobrancas/<?= (int) $c['id'] ?>"><?= V::e($c['reference']) ?></a></td><td><?= V::e($c['owner_name']) ?></td><td><?= V::e($c['plan_name']) ?></td><td><?= V::date($c['due_date'], false) ?></td><td class="num"><?= V::money($c['amount']) ?></td><td><?= V::badge($c['status'], V::CHARGE_STATUS[$c['status']] ?? $c['status']) ?></td></tr><?php endforeach; ?></tbody></table></div><?= V::pager($result) ?><?php endif; ?></div>
